using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Code = "CS", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Code = "MATH", Name = "Mathematics", Description = "Pure and applied mathematics, including statistics and data analysis." },
            new() { Id = 3, Code = "ENG", Name = "English", Description = "Literature, writing, and communication studies." },
            new() { Id = 4, Code = "PHYS", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 5, Code = "HIST", Name = "History", Description = "Exploration of past events and their impact on the modern world." },
            new() { Id = 6, Code = "BIO", Name = "Biology", Description = "Study of living organisms, genetics, and ecosystems." }
        };

        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Sarah Chen", Title = "Professor of Computer Science", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers and holds 3 patents in neural network architectures.", Email = "s.chen@university.edu" },
            new() { Id = 2, Name = "Dr. James Wilson", Title = "Associate Professor of Mathematics", Bio = "Dr. Wilson's research focuses on algebraic topology and its applications to data science. He received the Distinguished Teaching Award in 2023.", Email = "j.wilson@university.edu" },
            new() { Id = 3, Name = "Prof. Maria Garcia", Title = "Professor of English", Bio = "Prof. Garcia is a published novelist and literary critic specializing in contemporary American fiction and creative writing pedagogy.", Email = "m.garcia@university.edu" },
            new() { Id = 4, Name = "Dr. Robert Kim", Title = "Professor of Physics", Bio = "Dr. Kim conducts research in quantum computing and condensed matter physics. He previously worked at CERN on the Large Hadron Collider.", Email = "r.kim@university.edu" },
            new() { Id = 5, Name = "Dr. Emily Thompson", Title = "Associate Professor of History", Bio = "Dr. Thompson is an expert in early modern European history with a focus on the intersection of science, religion, and politics.", Email = "e.thompson@university.edu" },
            new() { Id = 6, Name = "Dr. Michael Okafor", Title = "Assistant Professor of Biology", Bio = "Dr. Okafor studies molecular genetics and CRISPR gene editing. His lab has made key contributions to understanding genetic disease mechanisms.", Email = "m.okafor@university.edu" },
            new() { Id = 7, Name = "Dr. Lisa Patel", Title = "Associate Professor of Computer Science", Bio = "Dr. Patel researches distributed systems and cloud computing. She previously spent 8 years as a senior engineer at a major tech company.", Email = "l.patel@university.edu" }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, Code = "CS101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control structures, functions, and basic data structures. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Room = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 120, CurrentEnrollment = 98 },
            new() { Id = 2, Code = "CS301", Title = "Data Structures & Algorithms", Description = "Advanced study of data structures including trees, graphs, and hash tables. Algorithm design and analysis with emphasis on time and space complexity.", Credits = 4, Schedule = "Tue/Thu 10:30 AM–12:00 PM", Room = "Science Hall 305", DepartmentId = 1, InstructorId = 7, IsFeatured = true, MaxEnrollment = 60, CurrentEnrollment = 55 },
            new() { Id = 3, Code = "CS420", Title = "Machine Learning", Description = "Introduction to machine learning concepts including supervised and unsupervised learning, neural networks, and model evaluation techniques.", Credits = 4, Schedule = "Mon/Wed 2:00–3:30 PM", Room = "Science Hall 410", DepartmentId = 1, InstructorId = 1, IsFeatured = true, MaxEnrollment = 45, CurrentEnrollment = 44 },
            new() { Id = 4, Code = "MATH201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors. Applications to computer science and engineering.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Room = "Math Building 102", DepartmentId = 2, InstructorId = 2, IsFeatured = false, MaxEnrollment = 80, CurrentEnrollment = 62 },
            new() { Id = 5, Code = "MATH301", Title = "Probability & Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis with real-world applications.", Credits = 4, Schedule = "Tue/Thu 1:00–2:30 PM", Room = "Math Building 205", DepartmentId = 2, InstructorId = 2, IsFeatured = true, MaxEnrollment = 70, CurrentEnrollment = 58 },
            new() { Id = 6, Code = "ENG101", Title = "College Writing", Description = "Develop essential academic writing skills including argumentation, research methods, and clear prose style. Frequent writing assignments with peer review.", Credits = 3, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Room = "Humanities 110", DepartmentId = 3, InstructorId = 3, IsFeatured = false, MaxEnrollment = 25, CurrentEnrollment = 24 },
            new() { Id = 7, Code = "ENG250", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present. Includes works by Hawthorne, Twain, Fitzgerald, Morrison, and contemporary authors.", Credits = 3, Schedule = "Tue/Thu 9:00–10:20 AM", Room = "Humanities 215", DepartmentId = 3, InstructorId = 3, IsFeatured = false, MaxEnrollment = 35, CurrentEnrollment = 28 },
            new() { Id = 8, Code = "PHYS101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Calculus-based introduction to physics with laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", Room = "Physics Lab 101", DepartmentId = 4, InstructorId = 4, IsFeatured = false, MaxEnrollment = 90, CurrentEnrollment = 72 },
            new() { Id = 9, Code = "PHYS350", Title = "Quantum Mechanics", Description = "Introduction to quantum theory: wave functions, Schrödinger equation, quantum operators, angular momentum, and applications to atomic physics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:30 PM", Room = "Physics Lab 302", DepartmentId = 4, InstructorId = 4, IsFeatured = true, MaxEnrollment = 30, CurrentEnrollment = 22 },
            new() { Id = 10, Code = "HIST101", Title = "World History to 1500", Description = "Survey of major civilizations and global interactions from ancient times to the early modern period.", Credits = 3, Schedule = "Tue/Thu 3:00–4:20 PM", Room = "Liberal Arts 120", DepartmentId = 5, InstructorId = 5, IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 76 },
            new() { Id = 11, Code = "HIST320", Title = "The Scientific Revolution", Description = "Examines the transformation of natural philosophy in Europe from Copernicus to Newton, and its social, religious, and political contexts.", Credits = 3, Schedule = "Mon/Wed 3:00–4:20 PM", Room = "Liberal Arts 210", DepartmentId = 5, InstructorId = 5, IsFeatured = false, MaxEnrollment = 40, CurrentEnrollment = 31 },
            new() { Id = 12, Code = "BIO101", Title = "Introduction to Biology", Description = "Fundamentals of cell biology, genetics, evolution, and ecology. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM + Lab Tue 2:00–4:00 PM", Room = "Life Sciences 101", DepartmentId = 6, InstructorId = 6, IsFeatured = false, MaxEnrollment = 100, CurrentEnrollment = 85 },
            new() { Id = 13, Code = "BIO410", Title = "Molecular Genetics", Description = "Advanced study of gene structure, expression, and regulation. Topics include CRISPR, epigenetics, and genomic medicine.", Credits = 4, Schedule = "Tue/Thu 10:00–11:30 AM", Room = "Life Sciences 305", DepartmentId = 6, InstructorId = 6, IsFeatured = true, MaxEnrollment = 35, CurrentEnrollment = 29 },
            new() { Id = 14, Code = "CS210", Title = "Web Development", Description = "Full-stack web development covering HTML, CSS, JavaScript, and server-side frameworks. Students build a complete web application.", Credits = 3, Schedule = "Tue/Thu 2:00–3:30 PM", Room = "Science Hall 215", DepartmentId = 1, InstructorId = 7, IsFeatured = false, MaxEnrollment = 50, CurrentEnrollment = 47 }
        };
    }

    public IReadOnlyList<Department> GetAllDepartments() => _departments.AsReadOnly();

    public Department? GetDepartmentById(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public Department? GetDepartmentByCode(string code) =>
        _departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public IReadOnlyList<Course> GetAllCourses() => _courses.AsReadOnly();

    public Course? GetCourseById(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        _courses.Where(c => c.IsFeatured).ToList().AsReadOnly();

    public IReadOnlyList<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList().AsReadOnly();

    public IReadOnlyList<Course> SearchCourses(string? searchTerm, int? departmentId, int? credits)
    {
        var query = _courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (credits.HasValue && credits.Value > 0)
        {
            query = query.Where(c => c.Credits == credits.Value);
        }

        return query.ToList().AsReadOnly();
    }

    public Instructor? GetInstructorById(int id) => _instructors.FirstOrDefault(i => i.Id == id);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class EnrollmentService
{
    private readonly List<EnrollmentRequest> _requests = new();

    public bool SubmitRequest(EnrollmentRequest request)
