@page "/"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>University Course Catalog</PageTitle>

<h1>Welcome to the University Course Catalog</h1>
<p class="lead">Browse our departments and courses for the current semester. Find the right courses for your academic journey.</p>

<hr />

<h2>🌟 Featured Courses</h2>
<div class="row">
    @foreach (var course in _featuredCourses)
    {
        var dept = CatalogService.GetDepartmentById(course.DepartmentId);
        <div class="col-md-6 col-lg-4 mb-4">
            <div class="card h-100">
                <div class="card-body">
                    <h5 class="card-title">@course.Code: @course.Title</h5>
                    <p class="card-text text-muted">@dept?.Name | @course.Credits credits</p>
                    <p class="card-text">@TruncateDescription(course.Description)</p>
                    <span class="badge bg-info">@course.Schedule</span>
                </div>
                <div class="card-footer">
                    <a href="courses/@course.Id" class="btn btn-primary btn-sm">View Details</a>
                    <span class="float-end text-muted small">@course.CurrentEnrollment/@course.MaxEnrollment enrolled</span>
                </div>
            </div>
        </div>
    }
</div>

<hr />

<h2>📚 Departments</h2>
<div class="row">
    @foreach (var dept in _departments)
    {
        <div class="col-md-6 col-lg-4 mb-3">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">@dept.Name</h5>
                    <p class="card-text">@dept.Description</p>
                    <a href="departments/@dept.Id" class="btn btn-outline-primary btn-sm">View Courses →</a>
                </div>
            </div>
        </div>
    }
</div>

@code {
    private IReadOnlyList<Course> _featuredCourses = Array.Empty<Course>();
    private IReadOnlyList<Department> _departments = Array.Empty<Department>();

    protected override void OnInitialized()
    {
        _featuredCourses = CatalogService.GetFeaturedCourses();
        _departments = CatalogService.GetAllDepartments();
    }

    private static string TruncateDescription(string description)
    {
        return description.Length > 120 ? description[..117] + "..." : description;
    }
}

@page "/courses"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@rendermode InteractiveServer
@inject CatalogService CatalogService

<PageTitle>Course Catalog</PageTitle>

<h1>Course Catalog</h1>
<p>Search and filter courses across all departments.</p>

<div class="row mb-4">
    <div class="col-md-4 mb-2">
        <input type="text" class="form-control" placeholder="Search courses..."
               @bind="SearchTerm" @bind:event="oninput" />
    </div>
    <div class="col-md-3 mb-2">
        <select class="form-select" @bind="SelectedDepartmentId">
            <option value="0">All Departments</option>
            @foreach (var dept in _departments)
            {
                <option value="@dept.Id">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 mb-2">
        <select class="form-select" @bind="SelectedCredits">
            <option value="0">Any Credits</option>
            <option value="3">3 Credits</option>
            <option value="4">4 Credits</option>
        </select>
    </div>
    <div class="col-md-3 mb-2">
        <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

<p class="text-muted">Showing @FilteredCourses.Count course(s)</p>

<table class="table table-striped table-hover">
    <thead>
        <tr>
            <th>Code</th>
            <th>Title</th>
            <th>Department</th>
            <th>Credits</th>
            <th>Schedule</th>
            <th>Availability</th>
            <th></th>
        </tr>
    </thead>
    <tbody>
        @foreach (var course in FilteredCourses)
        {
            var dept = CatalogService.GetDepartmentById(course.DepartmentId);
            var spotsLeft = course.MaxEnrollment - course.CurrentEnrollment;
            <tr>
                <td><strong>@course.Code</strong></td>
                <td>@course.Title</td>
                <td>@dept?.Name</td>
                <td>@course.Credits</td>
                <td><small>@course.Schedule</small></td>
                <td>
                    @if (spotsLeft <= 5)
                    {
                        <span class="badge bg-warning text-dark">@spotsLeft spots left</span>
                    }
                    else
                    {
                        <span class="badge bg-success">@spotsLeft spots left</span>
                    }
                </td>
                <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-primary">Details</a></td>
            </tr>
        }
    </tbody>
</table>

@code {
    private IReadOnlyList<Department> _departments = Array.Empty<Department>();

    private string _searchTerm = string.Empty;
    private int _selectedDepartmentId;
    private int _selectedCredits;

    private string SearchTerm
    {
        get => _searchTerm;
        set { _searchTerm = value; }
    }

    private int SelectedDepartmentId
    {
        get => _selectedDepartmentId;
        set { _selectedDepartmentId = value; }
    }

    private int SelectedCredits
    {
        get => _selectedCredits;
        set { _selectedCredits = value; }
    }

    private IReadOnlyList<Course> FilteredCourses =>
        CatalogService.SearchCourses(
            string.IsNullOrWhiteSpace(_searchTerm) ? null : _searchTerm,
            _selectedDepartmentId > 0 ? _selectedDepartmentId : null,
            _selectedCredits > 0 ? _selectedCredits : null);

    protected override void OnInitialized()
    {
        _departments = CatalogService.GetAllDepartments();
    }

    private void ClearFilters()
    {
        _searchTerm = string.Empty;
        _selectedDepartmentId = 0;
        _selectedCredits = 0;
    }
}

@page "/courses/{CourseId:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>@(_course?.Title ?? "Course Not Found")</PageTitle>

@if (_course is null)
{
    <h2>Course Not Found</h2>
    <p>The requested course could not be found.</p>
    <a href="courses" class="btn btn-primary">← Back to Catalog</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="departments/@_department?.Id">@_department?.Name</a></li>
            <li class="breadcrumb-item active">@_course.Code</li>
        </ol>
    </nav>

