@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>@(_course?.Title ?? "Course Not Found")</PageTitle>

@if (_course is null)
{
    <h2>Course Not Found</h2>
    <p>The requested course could not be found.</p>
    <a href="courses" class="btn btn-primary">← Back to Catalog</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="courses">Courses</a></li>
            <li class="breadcrumb-item"><a href="departments/@_department?.Id">@_department?.Name</a></li>
            <li class="breadcrumb-item active">@_course.Code</li>
        </ol>
    </nav>

    <div class="row">
        <div class="col-lg-8">
            <h1>@_course.Code: @_course.Title</h1>
            <p class="lead">@_course.Description</p>

            <div class="card mb-4">
                <div class="card-header">
                    <strong>Course Details</strong>
                </div>
                <div class="card-body">
                    <table class="table table-borderless mb-0">
                        <tbody>
                            <tr>
                                <th style="width: 150px;">Credits</th>
                                <td>@_course.Credits</td>
                            </tr>
                            <tr>
                                <th>Schedule</th>
                                <td>@_course.Schedule</td>
                            </tr>
                            <tr>
                                <th>Room</th>
                                <td>@_course.Room</td>
                            </tr>
                            <tr>
                                <th>Department</th>
                                <td>@_department?.Name (@_department?.Code)</td>
                            </tr>
                            <tr>
                                <th>Enrollment</th>
                                <td>
                                    @_course.CurrentEnrollment / @_course.MaxEnrollment
                                    @{
                                        var spotsLeft = _course.MaxEnrollment - _course.CurrentEnrollment;
                                    }
                                    @if (spotsLeft <= 5)
                                    {
                                        <span class="badge bg-warning text-dark ms-2">Only @spotsLeft spots remaining!</span>
                                    }
                                    else
                                    {
                                        <span class="badge bg-success ms-2">@spotsLeft spots available</span>
                                    }
                                </td>
                            </tr>
                        </tbody>
                    </table>
                </div>
            </div>

            <a href="enroll?courseId=@_course.Id" class="btn btn-primary">Request Enrollment →</a>
            <a href="courses" class="btn btn-outline-secondary ms-2">← Back to Catalog</a>
        </div>

        <div class="col-lg-4">
            @if (_instructor is not null)
            {
                <div class="card">
                    <div class="card-header">
                        <strong>Instructor</strong>
                    </div>
                    <div class="card-body">
                        <h5>@_instructor.Name</h5>
                        <p class="text-muted">@_instructor.Title</p>
                        <p>@_instructor.Bio</p>
                        <p><strong>Contact:</strong> <a href="mailto:@_instructor.Email">@_instructor.Email</a></p>
                    </div>
                </div>
            }
        </div>
    </div>
}

@code {
    [Parameter]
    public int CourseId { get; set; }

    private Course? _course;
    private Department? _department;
    private Instructor? _instructor;

    protected override void OnInitialized()
    {
        _course = CatalogService.GetCourseById(CourseId);
        if (_course is not null)
        {
            _department = CatalogService.GetDepartmentById(_course.DepartmentId);
            _instructor = CatalogService.GetInstructorById(_course.InstructorId);
        }
    }
}
