@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@rendermode InteractiveServer
@inject CatalogService CatalogService
@inject EnrollmentService EnrollmentService
@inject NavigationManager Navigation

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit a request to enroll in a course. All fields are required.</p>

@if (_submitted)
{
    <div class="alert alert-success" role="alert">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Your enrollment request for <strong>@_selectedCourseTitle</strong> has been submitted successfully.</p>
        <hr>
        <p class="mb-0">You will receive confirmation via your university email. <a href="courses">Browse more courses</a>.</p>
    </div>
}
else
{
    <div class="row">
        <div class="col-lg-8">
            <EditForm Model="_request" OnValidSubmit="HandleSubmit" FormName="enrollment">
                <DataAnnotationsValidator />
                <ValidationSummary class="text-danger" />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <InputText id="studentName" class="form-control" @bind-Value="_request.StudentName"
                               placeholder="Enter your full name" />
                    <ValidationMessage For="() => _request.StudentName" class="text-danger" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <InputText id="studentId" class="form-control" @bind-Value="_request.StudentId"
                               placeholder="e.g., CS123456" />
                    <ValidationMessage For="() => _request.StudentId" class="text-danger" />
                    <div class="form-text">Format: 2 uppercase letters followed by 6 digits</div>
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <InputSelect id="courseId" class="form-select" @bind-Value="_request.CourseId">
                        <option value="0">— Select a course —</option>
                        @foreach (var course in _courses)
                        {
                            var dept = CatalogService.GetDepartmentById(course.DepartmentId);
                            <option value="@course.Id">@course.Code - @course.Title (@dept?.Code)</option>
                        }
                    </InputSelect>
                    <ValidationMessage For="() => _request.CourseId" class="text-danger" />
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
                <a href="courses" class="btn btn-outline-secondary ms-2">Cancel</a>
            </EditForm>
        </div>

        <div class="col-lg-4">
            <div class="card bg-light">
                <div class="card-body">
                    <h5 class="card-title">ℹ️ Information</h5>
                    <ul class="small">
                        <li>Enrollment requests are processed within 2 business days.</li>
                        <li>You will be notified by email once your request is reviewed.</li>
                        <li>Prerequisites are verified during processing.</li>
                        <li>If a course is full, you may be placed on a waitlist.</li>
                    </ul>
                </div>
            </div>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery(Name = "courseId")]
    private int? PreselectedCourseId { get; set; }

    private EnrollmentRequest _request = new();
    private IReadOnlyList<Course> _courses = Array.Empty<Course>();
    private bool _submitted;
    private string _selectedCourseTitle = string.Empty;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetAllCourses();

        if (PreselectedCourseId.HasValue && PreselectedCourseId.Value > 0)
        {
            _request.CourseId = PreselectedCourseId.Value;
        }
    }

    private void HandleSubmit()
    {
        var course = CatalogService.GetCourseById(_request.CourseId);
        _selectedCourseTitle = course is not null ? $"{course.Code}: {course.Title}" : "Unknown Course";

        EnrollmentService.SubmitRequest(_request);
        _submitted = true;
    }
}

